def rearrangeString(s, x, y):
    # Collect every y first, then everything else, then every x last
    ys = []
    others = []
    xs = []
    for ch in s:
        if ch == y:
            ys.append(ch)
        elif ch == x:
            xs.append(ch)
        else:
            others.append(ch)
    # Every y now precedes every x; the result is a permutation of s
    return "".join(ys) + "".join(others) + "".join(xs)
